content.css:
.kit-root {
  forced-color-adjust: none;
  position: relative;
  overflow: hidden;
  font-family: var(--kit-font);
  font-size: var(--kit-size);
  color: var(--kit-fg);
}
.kit-layer {
  position: absolute;
  left: 0;
  top: 0;
}
.kit-html {
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.kit-html .kit-ui,
.kit-html .kit-top,
.kit-html .kit-top * {
  pointer-events: auto;
}
.kit-svg:focus {
  outline: none;
}
.kit-svg:focus-visible {
  outline: 2px solid var(--kit-selected);
  outline-offset: -2px;
}
.kit-top {
  position: absolute;
  left: var(--kit-pad);
  right: var(--kit-pad);
  top: calc(var(--kit-pad) + var(--kit-head) * 1.5 + 4px);
  display: flex;
  gap: var(--kit-gap);
  align-items: center;
  flex-wrap: wrap;
}
.kit-headline {
  position: absolute;
  left: var(--kit-pad);
  right: var(--kit-pad);
  top: var(--kit-pad);
  font-size: var(--kit-head);
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kit-pills {
  display: inline-flex;
  gap: 4px;
  padding: 3px;
  border-radius: 999px;
  background: var(--kit-panel);
}
.kit-pill,
.kit-back,
button.kit-crumb {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
  border-radius: 999px;
  padding: 4px 12px;
  font: inherit;
  color: var(--kit-fg2);
  background: transparent;
  cursor: pointer;
}
.kit-pill.is-on {
  color: var(--kit-bg);
  background: var(--kit-accent);
}
.kit-pill:focus-visible,
.kit-back:focus-visible,
.kit-crumb:focus-visible,
.kit-card:focus-visible,
.kit-label.is-link:focus-visible {
  outline: 2px solid var(--kit-selected);
  outline-offset: 2px;
}
.kit-nav {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.kit-crumb-sep {
  color: var(--kit-fg2);
}
.kit-label {
  paint-order: stroke;
  stroke: var(--kit-bg);
  stroke-width: 4px;
  stroke-linejoin: round;
  fill: var(--kit-fg2);
  font-size: var(--kit-size);
}
.kit-label.is-tick {
  font-size: calc(var(--kit-size) * 0.9);
}
.kit-label.is-link {
  fill: var(--kit-fg);
  cursor: pointer;
  text-decoration: underline;
}
.kit-focus {
  fill: none;
  stroke: var(--kit-selected);
  stroke-width: 2;
}
.kit-live {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
.kit-card {
  position: absolute;
  box-sizing: border-box;
  padding: var(--kit-pad);
  border-radius: var(--kit-radius);
  background: var(--kit-panel);
  box-shadow: var(--kit-shadow);
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: hidden;
}
.kit-card[role="button"] {
  cursor: pointer;
}
.kit-card-head {
  display: flex;
  gap: 6px;
  align-items: center;
  color: var(--kit-fg2);
}
.kit-card-value {
  font-size: var(--kit-head);
  font-weight: 600;
}
.kit-card-note {
  color: var(--kit-fg2);
}
.kit-state {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  text-align: center;
  padding: var(--kit-pad);
  color: var(--kit-fg2);
}
.kit-state-title {
  font-weight: 600;
  color: var(--kit-fg);
}
.kit-state.kit-banner {
  inset: auto var(--kit-pad) var(--kit-pad) auto;
  flex-direction: row;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--kit-panel);
}
.kit-banner .kit-state-title {
  display: none;
}
.kit-hc .kit-pill.is-on {
  color: var(--kit-bg);
  background: var(--kit-selected);
}
.kit-hc {
  background: var(--kit-bg);
}
.kit-hc .kit-card,
.kit-hc .kit-pills {
  border: 1px solid var(--kit-fg);
}
.kit-brush rect.selection {
  fill: var(--kit-accent);
  fill-opacity: 0.12;
  stroke: var(--kit-accent);
}
/* the frame meter (debug; kit/perf.ts) */
.kit-meter {
  position: absolute;
  left: 4px;
  bottom: 4px;
  z-index: 10;
  padding: 4px 6px;
  border-radius: 4px;
  background: var(--kit-bg);
  border: 1px solid var(--kit-fg2);
  color: var(--kit-fg);
  font: 12px/1.35 Consolas, "Courier New", monospace;
  pointer-events: none;
  white-space: pre;
}
.kit-meter .is-bad {
  color: var(--kit-selected);
  font-weight: 700;
}
/* a small chip that clears the visual's own click filter */
.kit-clear {
  position: absolute;
  top: var(--kit-pad);
  right: var(--kit-pad);
  z-index: 4;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  border-radius: 999px;
  border: 1px solid var(--kit-selected);
  background: var(--kit-bg);
  color: var(--kit-fg);
  font: inherit;
  font-size: var(--kit-size);
  cursor: pointer;
}
.kit-clear:focus-visible {
  outline: 2px solid var(--kit-selected);
}
/* screen changes and in-place morphs (kit/morph.ts): ghosts of shared elements fly above both screens */
.kit-morph-fly {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}
.kit-morph-ghost {
  position: absolute;
  will-change: left, top, width, height;
}
.kit-morph-out {
  pointer-events: none;
}
.kit-root.has-clear .kit-headline {
  right: calc(var(--kit-pad) + 96px);
}
/* loading placeholders while Desktop queries (kit/scene.ts placeholder) */
.kit-skeleton {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.kit-sk {
  position: absolute;
  border-radius: 6px;
  background: var(--kit-fg2);
  opacity: 0.12;
  animation: kit-sk-pulse 1.6s ease-in-out infinite;
}
.kit-sk-dot {
  border-radius: 50%;
}
.kit-sk-space {
  border-radius: var(--kit-radius, 8px);
  opacity: 0.08;
}
@keyframes kit-sk-pulse {
  0%,
  100% {
    opacity: 0.12;
  }
  50% {
    opacity: 0.06;
  }
}
@media (prefers-reduced-motion: reduce) {
  .kit-sk {
    animation: none;
  }
}
.kit-hc .kit-sk {
  background: none;
  border: 1px dashed var(--kit-fg);
  opacity: 1;
  animation: none;
}
/* the docked readout (focus-dim): details beside the drawing, never over it */
.kit-readout {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  box-sizing: border-box;
  /* its width is the space the drawing keeps clear (padding inside it, v1.11.2) */
  overflow: hidden;
  padding: var(--kit-pad);
  background: var(--kit-panel);
  border-left: 1px solid var(--kit-line, rgba(127, 127, 127, 0.2));
  color: var(--kit-fg);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.kit-readout-title {
  font-size: var(--kit-head);
  font-weight: 600;
}
.kit-readout-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-variant-numeric: tabular-nums;
}
.kit-readout-note {
  color: var(--kit-fg2);
}
.kit-zone {
  cursor: pointer;
  outline: none;
}
.kit-zone:focus-visible {
  stroke: var(--kit-selected);
  stroke-width: 2px;
}
